param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
$sourcePath=Join-Path $RepositoryRoot AIConflictCore/Scripts/Game/AIConflict/Loadouts/AICF_DroppedWeaponFallSafety.c
$source=[IO.File]::ReadAllText($sourcePath)
$sourceSha=(Get-FileHash $sourcePath -Algorithm SHA256).Hash
if($source-match'\b(SetOrigin|SetVelocity|SetHealth|SetLifeState|Teleport|EjectOccupant|Kill)\s*\('){throw 'Fall safety gained actor/physics/health effects'}
if(([regex]::Matches($source,'RplComponent.DeleteRplEntity\(item, false\)')).Count-ne1){throw 'Single owned weapon deletion boundary changed'}
function Replay([string]$s){
 $s=$s.Replace('override protected ','public override ').Replace('protected ','public ').Replace('ref ','').Replace('super.','base.')
 $s=$s.Replace('EntityID.INVALID','0L').Replace('EntityID','long').Replace('vector','Vec').Replace('System.GetTickCount()','Runtime.Now').Replace('GetGame()','Runtime.Game').Replace('Math.AbsFloat(','Math.Abs(').Replace('float.MAX','float.MaxValue').Replace('string.Format(','Fmt.Format(')
 $s=$s.Replace('static const ','public const ')
 $s=[regex]::Replace($s,'(?m)^class (AICF_\w+)\s*$','public class $1:Native')
 $s=$s.Replace('modded class ScriptedInventoryStorageManagerComponent','public class ScriptedInventoryStorageManagerComponent:NativeScriptedManager')
 $s=[regex]::Replace($s,'(?m)^\t(static )?(bool|void|AICF_DroppedWeaponInventoryFrame) (\w+)\(','public $1$2 $3(')
 $s=[regex]::Replace($s,'(?m)^\t(?!public\b)([\w<>]+) (m_\w+)(\s*=\s*[^;]+)?;',"`tpublic `$1 `$2`$3;")
 $s=[regex]::Replace($s,'array<([^>]+)>','EArray<$1>')
 $s=[regex]::Replace($s,'(EArray<([^>]+)>\s+\w+\s*=\s*)\{([^}]*)\};','$1new EArray<$2>{$3};')
 $s=[regex]::Replace($s,'foreach \(([^:]+) : ([^)]+)\)','foreach ($1 in $2)')
 $s=[regex]::Replace($s,'for \(int (index|axis|count|i);','for (int $1=0;')
 $s=[regex]::Replace($s,'FindComponent\((\w+)\)','FindComponent(typeof($1))')
 return $s
}
